#!/usr/bin/env bash\n# Tests for coffee.sh\n\nset -e\n\n# Path to the script relative to this test file\nSCRIPT="../src/coffee.sh"\n\n# Test that a specific style argument yields the expected output\noutput=$($SCRIPT "Espresso")\nif [[ "$output" != *"Espresso"* ]]; then\n  echo "FAIL: Expected Espresso in output"\n  exit 1\nfi\n\n# Test that a random invocation contains one of the known styles\noutput=$($SCRIPT)\nfound=0\nfor style in Espresso Drip "French Press" "Cold Brew" Turkish "Moka Pot"; do\n  if [[ "$output" == *"$style"* ]]; then\n    found=1\n    break\n  fi\ndone\nif [[ $found -ne 1 ]]; then\n  echo "FAIL: Random output did not contain a known style"\n  exit 1\nfi\n\necho "All tests passed."
